-- seed.sql: seed varieties. Generated by data/seed_varieties/build_seed.py from
-- seed_varieties.csv; change the CSV and build again. Safe to run more than once.
-- Needs 20261105_season_seeds.sql first.

begin;

insert into public.seed_varieties (crop_id, name, breeder, active, source) values
  ('barley', 'ZHANA', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'FORTUNA', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'FATIMA', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'LEXY', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'Achilios', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'Andromeda', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder'),
  ('barley', 'Antar', null, 'true', 'Name from the barley variety list in the screenshot; add the breeder')
on conflict (crop_id, name) do update set
  breeder = excluded.breeder,
  active = excluded.active,
  source = excluded.source;

commit;

